35	  // guest, or one derived from the account profile) plus that account profile
36	  // (null for the guest path) so "quit to worlds" returns to the right list.
37	  | { name: "play-online"; profile: Profile; world: OnlineWorld; session: NetworkSession; onlineProfile: OnlineProfile | null };
