91	export default function GameShell() {
92	  const [ready, setReady] = useState(false);
93	  const [screen, setScreen] = useState<Screen>({ name: "profile-select" });
94	  const [reloadNonce, setReloadNonce] = useState(0);
95	  const [connecting, setConnecting] = useState<string | null>(null);
96	  const [connectError, setConnectError] = useState<string | null>(null);
97	  // A join is in flight — guards against a double-click opening (and leaking) a
98	  // second socket. A ref, not `connecting`, so it's set synchronously.
99	  const joiningRef = useRef(false);
100	  // The signed-in account (a real, non-anonymous one flips the menu into
101	  // account mode). Offline-first: never asked until this browser went online.
102	  const [onlineUser, setOnlineUser] = useState<OnlineUser | null>(null);
103	  const refreshOnlineUser = useCallback(() => {
104	    if (onlineUsed()) void currentUser().then(setOnlineUser);
105	  }, []);
106	
107	  /**
108	   * Open a world for play. A cloud-linked one (WorldMeta.cloudId) reconciles
109	   * first: pull the remote save if it advanced past this device's cursor, write
110	   * it to disk, and boot from disk like any other world — reusing the "Opening…"
111	   * gate. The caller owns the `joiningRef` guard (this helper does not), so the
112	   * materialize-then-open path can hold it across `createWorld` too.
113	   */
114	  const openWorld = async (profileId: string, worldId: string) => {
115	    const world = getWorld(worldId);
116	    touchWorld(worldId);
117	    writeSessionPointer({ profileId, worldId });
118	    if (world?.cloudId) {
119	      setConnecting(world.name);
120	      try {
121	        const decision = await pullCloudSaveIfNewer(world.cloudId);
122	        if (decision.adopt) writeSave(worldSaveKey(worldId), decision.save);
123	      } catch {
124	        // Offline or a bad blob → fall through and play the local copy.
125	      } finally {
126	        setConnecting(null);
127	      }
128	    }
129	    setScreen({ name: "play", profileId, worldId });
130	  };
131	
132	  const playLocal = async (profileId: string, worldId: string) => {
133	    if (joiningRef.current) return;
134	    joiningRef.current = true;
135	    try {
136	      await openWorld(profileId, worldId);
137	    } finally {
138	      joiningRef.current = false;
139	    }
140	  };
141	
142	  /** Materialize a cloud save as a local world (linked by cloudId), then open it — the pull-on-open fills it in. */
143	  const downloadCloud = async (profileId: string, world: OnlineWorld) => {
144	    // Guard BEFORE createWorld so a fast double-click can't persist two local
145	    // worlds sharing the same cloudId (the second open would just be dropped).
146	    if (joiningRef.current) return;
147	    joiningRef.current = true;
148	    try {
149	      const local = createWorld(profileId, world.name, String(world.seed), {
150	        worldType: world.worldType as WorldMeta["worldType"],
151	        gameMode: world.gameMode as WorldMeta["gameMode"],
152	        difficulty: world.difficulty as WorldMeta["difficulty"],
153	        hardcore: world.hardcore,
154	        worldgenVersion: world.worldgenVersion,
155	        cloudId: world.id
156	      });
157	      await openWorld(profileId, local.id);
158	    } finally {
159	      joiningRef.current = false;
160	    }
161	  };
162	
163	  /** Guest-or-account → ticket → socket → replica sync → play. When an account
164	   *  profile is given, its id rides the ticket so the roster shows that profile. */
165	  const playOnline = async (profile: Profile, world: OnlineWorld, onlineProfile: OnlineProfile | null) => {
166	    if (joiningRef.current) return; // a join is already in flight
167	    joiningRef.current = true;
168	    setConnectError(null);
169	    setConnecting(world.name);
170	    const ticketProfileId = onlineProfile?.id;
171	    try {
172	      if (!(await ensureSignedIn())) throw new Error("sign-in failed");
173	      const grant = await requestJoinTicket(world.id, ticketProfileId);
174	      if (!grant) throw new Error("could not get a join ticket (is the game server configured?)");
175	      // The reconnect ladder mints a fresh short-lived ticket each retry — the
176	      // 60 s TTL means a stale one is useless a minute after a drop.
177	      const session = await connectNetworkSession(grant.gameServerUrl, grant.ticket, undefined, {
178	        reconnect: async () => {
179	          const next = await requestJoinTicket(world.id, ticketProfileId);
180	          return next ? { url: next.gameServerUrl, ticket: next.ticket } : null;
181	        }
182	      });
183	      setScreen({ name: "play-online", profile, world, session, onlineProfile });
184	    } catch (error) {
185	      setConnectError(error instanceof Error ? error.message : "connection failed");
186	    } finally {
187	      setConnecting(null);
188	      joiningRef.current = false;
189	    }
190	  };
191	
192	  useEffect(() => {
193	    installUiTiles(); // the menu chrome shares the in-game noise tiles
194	    migrateLegacySave();
195	    // Resume the tab's world if one was being played and still exists.
196	    const pointer = readSessionPointer();
197	    const resume: Screen | null =
198	      pointer && getProfile(pointer.profileId) && getWorld(pointer.worldId) ? { name: "play", profileId: pointer.profileId, worldId: pointer.worldId } : null;
199	    // Microtask hop keeps this off the synchronous effect path (cascading-render lint).
200	    queueMicrotask(() => {
201	      if (resume) setScreen(resume);
202	      setReady(true);
203	    });
204	  }, []);
205	
206	  // Discover an existing account session so a signed-in reload lands in account
207	  // mode (offline-first: refreshOnlineUser no-ops until this browser went online).
208	  useEffect(() => refreshOnlineUser(), [refreshOnlineUser]);
209	
210	  // The "Opening…" gate and join-failure dialog, shared by both world lists.
211	  const netModals = (
212	    <>
213	      {connecting && (
214	        <div className="net-modal" role="status">
215	          <div className="net-modal-box">Opening “{connecting}”…</div>
216	        </div>
217	      )}
218	      {connectError && (
219	        <div className="net-modal" role="alertdialog" aria-label="Connection failed">
220	          <div className="net-modal-box">
221	            <p>Couldn&apos;t join: {connectError}</p>
222	            <button type="button" className="mc-button" onClick={() => setConnectError(null)}>
223	              OK
224	            </button>
225	          </div>
226	        </div>
227	      )}
228	    </>
229	  );
230	
231	  // localStorage is read below; hold the neutral frame until we're client-side.
232	  if (!ready) return <div className="menu-screen" />;
233	
234	  if (screen.name === "play") {
235	    const profile = getProfile(screen.profileId);
236	    const world = getWorld(screen.worldId);
237	    // Both exist in normal flow; a cross-tab delete drops us back to a menu.
238	    if (profile && world) {
239	      return (
240	        <MinecraftGame
241	          key={`${world.id}:${reloadNonce}`}
242	          world={world}
243	          profile={profile}
244	          onQuitToWorlds={() => {
245	            writeSessionPointer(null);
246	            setScreen({ name: "world-select", profileId: profile.id });
247	          }}
248	          onDeleteWorld={() => {
249	            deleteWorld(world.id); // hardcore Game Over: erase the dead world and leave
250	            writeSessionPointer(null);
251	            setScreen({ name: "world-select", profileId: profile.id });
252	          }}
253	          onReloadWorld={() => setReloadNonce((nonce) => nonce + 1)}
254	        />
255	      );
256	    }
257	  }
258	
259	  if (screen.name === "play-online") {
260	    // Quit returns to the account profile's online worlds, or (guest path) the
261	    // local world list the join came from.
262	    const backToWorlds: Screen = screen.onlineProfile
263	      ? { name: "online-worlds", profile: screen.onlineProfile }
264	      : { name: "world-select", profileId: screen.profile.id };
265	    return (
266	      <MinecraftGame
267	        key={`online:${screen.world.id}`}
268	        world={onlineWorldMeta(screen.world, screen.profile.id)}
269	        profile={screen.profile}
270	        online={screen.session}
271	        onQuitToWorlds={() => setScreen(backToWorlds)}
272	        onDeleteWorld={() => {
273	          // Hardcore game-over: actually delete the shared world on the server
274	          // (owner-gated; a member just leaves), then return to the list.
275	          screen.session.dispose();
276	          void deleteOnlineWorld(screen.world.id);
277	          setScreen(backToWorlds);
278	        }}
279	        onReloadWorld={() => setScreen(backToWorlds)}
280	      />
281	    );
282	  }
283	
284	  if (screen.name === "world-select") {
285	    const profile = getProfile(screen.profileId);
286	    if (profile) {
287	      return (
288	        <>
289	          <WorldSelect
290	            profile={profile}
291	            onPlay={(worldId) => void playLocal(profile.id, worldId)}
292	            onPlayOnline={(world) => void playOnline(profile, world, null)}
293	            onDownloadCloud={(world) => void downloadCloud(profile.id, world)}
294	            onBack={() => setScreen({ name: "profile-select" })}
295	          />
296	          {netModals}
297	        </>
298	      );
299	    }
300	  }
301	
302	  if (screen.name === "online-worlds") {
303	    return (
304	      <>
305	        <OnlineWorldSelect
306	          profile={screen.profile}
307	          onPlay={(world) => void playOnline(profileFromOnline(screen.profile), world, screen.profile)}
308	          onBack={() => setScreen({ name: "profile-select" })}
309	        />
310	        {netModals}
311	      </>
312	    );
313	  }
314	
315	  // The profile-select screen is auth-aware: a signed-in account browses its
316	  // synced online profiles; everyone else gets the local (browser) profiles.
317	  if (onlineUser && !onlineUser.isAnonymous) {
318	    return (
319	      <AccountProfileSelect user={onlineUser} onPlay={(profile) => setScreen({ name: "online-worlds", profile })} onSignedOut={() => setOnlineUser(null)} />
320	    );
321	  }
322	
323	  return (
324	    <ProfileSelect
325	      onPlay={(profileId) => {
326	        setActiveProfile(profileId);
327	        setScreen({ name: "world-select", profileId });
328	      }}
329	      onAuthChange={refreshOnlineUser}
330	    />
331	  );
332	}
