1	"use client";
2	
3	import { useEffect, useState } from "react";
4	import { authClient, currentUser, ensureSignedIn, markOnlineUsed, onlineUsed, type OnlineUser } from "@/lib/auth/client";
5	
6	/**
7	 * The account corner of the menu: shows who you are online, offers instant
8	 * guest play, and upgrades a guest to a real account without losing worlds
9	 * (the server re-parents them — see lib/auth/server.ts). Purely additive to
10	 * the offline game: with no online features touched, no account ever exists.
11	 */
12	type AccountPanelProps = {
13	  /** Notified after any auth mutation (sign in/up/out, guest) so a parent shell
14	   *  can react — e.g. flip the menu into account mode. */
15	  onAuthChange?: () => void;
16	};
17	
18	export default function AccountPanel({ onAuthChange }: AccountPanelProps) {
19	  const [user, setUser] = useState<OnlineUser | null>(null);
20	  const [mode, setMode] = useState<"closed" | "signin" | "signup">("closed");
21	  const [email, setEmail] = useState("");
22	  const [password, setPassword] = useState("");
23	  const [name, setName] = useState("");
24	  const [busy, setBusy] = useState(false);
25	  const [error, setError] = useState<string | null>(null);
26	
27	  useEffect(() => {
28	    // Offline-first: never even ask the server about a session until this
29	    // browser has used online features once (see lib/auth/client.ts).
30	    if (onlineUsed()) void currentUser().then(setUser);
31	  }, []);
32	
33	  const refresh = async () => {
34	    setUser(await currentUser());
35	    onAuthChange?.();
36	  };
37	  // Mirror submit / "Play online as guest": guard against a failed request (no
38	  // unhandled rejection, a visible error) and against concurrent double-clicks.
39	  const signOut = async () => {
40	    setBusy(true);
41	    setError(null);
42	    try {
43	      await authClient().signOut();
44	      await refresh();
45	    } catch {
46	      setError("Couldn't reach the server — check your connection and try again.");
47	    } finally {
48	      setBusy(false);
49	    }
50	  };
51	
52	  const submit = async (event: React.FormEvent) => {
53	    event.preventDefault();
54	    setBusy(true);
55	    setError(null);
56	    markOnlineUsed();
57	    // Sign-up (and sign-in) while holding a guest session links the account:
58	    // the guest's worlds move over server-side before the guest is deleted.
59	    try {
60	      const result =
61	        mode === "signup"
62	          ? await authClient().signUp.email({ email, password, name: name.trim() || email.split("@")[0] })
63	          : await authClient().signIn.email({ email, password });
64	      if (result.error) {
65	        setError(result.error.message ?? "That didn't work — check the details and try again.");
66	        return;
67	      }
68	      setMode("closed");
69	      setPassword("");
70	      await refresh();
71	    } catch {
72	      // A thrown request (network failure) instead of an { error } result.
73	      setError("Couldn't reach the server — check your connection and try again.");
74	    } finally {
75	      setBusy(false);
76	    }
77	  };
78	
79	  if (mode !== "closed") {
80	    return (
81	      <form className="menu-form account-panel" onSubmit={submit}>
82	        <label className="menu-field">
83	          Email
84	          <input className="menu-input" type="email" required value={email} onChange={(e) => setEmail(e.target.value)} />
85	        </label>
86	        {mode === "signup" && (
87	          <label className="menu-field">
88	            Display name
89	            <input className="menu-input" value={name} maxLength={24} onChange={(e) => setName(e.target.value)} />
90	          </label>
91	        )}
92	        <label className="menu-field">
93	          Password
94	          <input className="menu-input" type="password" required minLength={8} value={password} onChange={(e) => setPassword(e.target.value)} />
95	        </label>
96	        {error && <div className="account-error">{error}</div>}
97	        <div className="menu-form-actions">
98	          <button type="submit" className="mc-button" disabled={busy}>
99	            {mode === "signup" ? (user?.isAnonymous ? "Create account (keeps your worlds)" : "Create account") : "Sign in"}
100	          </button>
101	          <button type="button" className="mc-button" onClick={() => setMode(mode === "signup" ? "signin" : "signup")}>
102	            {mode === "signup" ? "I have an account" : "I need an account"}
103	          </button>
104	          <button type="button" className="mc-button" onClick={() => setMode("closed")}>
105	            Cancel
106	          </button>
107	        </div>
108	      </form>
109	    );
110	  }
111	
112	  return (
113	    <div className="account-panel">
114	      {user ? (
115	        <>
116	          <span className="account-status">{user.isAnonymous ? "Playing as guest" : `Signed in as ${user.name}`}</span>
117	          {user.isAnonymous ? (
118	            <>
119	              <button type="button" className="mc-button" onClick={() => setMode("signup")} disabled={busy}>
120	                Keep my worlds — create account
121	              </button>
122	              {/* A guest could previously never get back to the login screen; sign
123	                  out drops to the "Offline" state where Sign in / register live. */}
124	              <button type="button" className="mc-button" onClick={signOut} disabled={busy}>
125	                Sign out
126	              </button>
127	            </>
128	          ) : (
129	            <button type="button" className="mc-button" onClick={signOut} disabled={busy}>
130	              Sign out
131	            </button>
132	          )}
133	          {error && <div className="account-error">{error}</div>}
134	        </>
135	      ) : (
136	        <>
137	          <span className="account-status">Offline</span>
138	          <button
139	            type="button"
140	            className="mc-button"
141	            onClick={async () => {
142	              setBusy(true);
143	              setError(null);
144	              try {
145	                await ensureSignedIn();
146	                await refresh();
147	              } catch {
148	                setError("Couldn't reach the server — check your connection and try again.");
149	              } finally {
150	                setBusy(false);
151	              }
152	            }}
153	            disabled={busy}
154	          >
155	            Play online as guest
156	          </button>
157	          <button type="button" className="mc-button" onClick={() => setMode("signin")}>
158	            Sign in
159	          </button>
160	          {error && <div className="account-error">{error}</div>}
161	        </>
162	      )}
163	    </div>
164	  );
165	}
166

