11	  return {
12	    id,
13	    name: `W-${id}`,
14	    kind: "mp",
15	    seed: 1,
16	    worldType: "default",
17	    gameMode: "survival",
18	    difficulty: "normal",
19	    hardcore: false,
20	    worldgenVersion: 11,
21	    role: "owner",
22	    profileId,
23	    updatedAt: "2026-07-04T00:00:00.000Z",
24	    ...overrides
25	  };
26	}
